import { RUNTIME_IMPLEMENTATION_METADATA } from "./implementation.ts";

export function generatedSourceBanner(options: {
  readonly parserPlanVersion?: number;
  readonly parserPlanSemantics?: string;
} = {}): string {
  const lines = [
    "// Generated by @mewhhaha/baba.",
    options.parserPlanVersion === undefined
      ? "// Parser plan version: unavailable."
      : `// Parser plan version: ${options.parserPlanVersion}.`,
    options.parserPlanSemantics === undefined
      ? "// Parser plan semantics: unavailable."
      : `// Parser plan semantics: ${options.parserPlanSemantics}.`,
    `// Runtime semantics version: ${RUNTIME_IMPLEMENTATION_METADATA.version}.`,
    `// Runtime semantics: ${RUNTIME_IMPLEMENTATION_METADATA.semantics}.`,
    "// Do not edit; regenerate from grammar.baba.",
  ];
  return lines.join("\n");
}
